from docx import Document
from pathlib import Path
paths = {
    'template': next((Path.home()/'Downloads').glob('2026 首届 openvela AI 硬件开发者大赛 - 作品提交模板.docx')),
    'report': Path.home()/'Desktop'/'实验报告.docx',
}
for name,path in paths.items():
    doc=Document(path)
    print(f'===== {name} {path} paragraphs =====')
    for i,p in enumerate(doc.paragraphs):
        txt=p.text.strip()
        if txt:
            print(f'{i:03d} [{p.style.name}] {txt}')
    print(f'===== {name} tables =====')
    for ti,t in enumerate(doc.tables):
        print(f'-- table {ti} rows={len(t.rows)} cols={len(t.columns)}')
        for ri,row in enumerate(t.rows[:40]):
            cells=[' '.join(c.text.split()) for c in row.cells]
            print(f'  r{ri}: {cells}')
